import{_ as r,C as o,c as i,o as n,ag as s,j as a,G as l}from"./chunks/framework.Bw-5EFTY.js";const v=JSON.parse('{"title":"Admin Dashboard Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin-portal/admin-dashboard-overview.md","filePath":"guide/admin-portal/admin-dashboard-overview.md","lastUpdated":1756121525000}'),h={name:"guide/admin-portal/admin-dashboard-overview.md"};function d(f,e,g,m,u,p){const t=o("ZoomableImage");return n(),i("div",null,[e[0]||(e[0]=s('<h1 id="admin-dashboard-overview" tabindex="-1">Admin Dashboard Overview <a class="header-anchor" href="#admin-dashboard-overview" aria-label="Permalink to &quot;Admin Dashboard Overview&quot;">​</a></h1><p>FluentAffiliate makes it easy to manage all your affiliate activity right from your WordPress dashboard. As the admin, you&#39;ll get a clear and simple view of how your affiliate program is performing in your FluentAffiliate Admin dashboard.</p><p>From this dashboard, you&#39;ll see key stats like <a href="/guide/admin-portal/payout-management">payouts</a>, earnings, <a href="/guide/admin-portal/managing-referrals">referrals</a>, visits, and more, all in one place. It helps you stay on top of what your <a href="/guide/admin-portal/managing-affiliates">affiliates</a> are doing and how they&#39;re performing.</p><h3 id="what-you-ll-see-on-the-dashboard" tabindex="-1">What You&#39;ll See on the Dashboard <a class="header-anchor" href="#what-you-ll-see-on-the-dashboard" aria-label="Permalink to &quot;What You&#39;ll See on the Dashboard&quot;">​</a></h3><p>Let&#39;s take a look at the different sections of the dashboard and what they tell you.</p><h2 id="key-performance-metrics" tabindex="-1">Key Performance Metrics <a class="header-anchor" href="#key-performance-metrics" aria-label="Permalink to &quot;Key Performance Metrics&quot;">​</a></h2><p>At the top of the dashboard, you&#39;ll find a series of boxes showing your most important stats:</p><ul><li><strong>Total Paid:</strong> The amount they&#39;ve already received in payout.</li><li><strong>Total Unpaid:</strong> The total amount of approved commissions that are waiting to be paid.</li><li><strong>Active Affiliates:</strong> The number of approved affiliates in your program.</li><li><strong>Total Visits:</strong> The number of visits their <a href="/guide/affiliate-portal/generating-affiliate-links">affiliate links</a> have received.</li><li><strong>Total Referrals:</strong> How many referral they&#39;ve successfully brought in.</li><li><strong>Conversion Rate:</strong> The percentage of visits that have turned into successful referrals.</li><li><strong>Pending Affiliates:</strong> The number of new affiliate applications that are awaiting your approval.</li><li><strong>Total Order Value by Referrals:</strong> The total revenue amount generated from all affiliate referrals.</li></ul><h3 id="dark-mode-light-mode-toggle" tabindex="-1">Dark Mode / Light Mode Toggle <a class="header-anchor" href="#dark-mode-light-mode-toggle" aria-label="Permalink to &quot;Dark Mode / Light Mode Toggle&quot;">​</a></h3><p>In the top-right corner of your dashboard, next to the <strong>Settings</strong> button, you&#39;ll find the display mode toggle. Simply click the <strong>moon</strong> icon to switch the entire interface to a <strong>dark</strong> theme, which can be easier on the eyes in low-light environments. To switch back, click the <strong>sun</strong> icon that appears in its place.</p><h4 id="growth-overview" tabindex="-1">Growth Overview <a class="header-anchor" href="#growth-overview" aria-label="Permalink to &quot;Growth Overview&quot;">​</a></h4><p>Below the main stats, the Growth Overview graph gives you a visual representation of your program&#39;s performance over time.</p><ul><li><p>You can filter the graph to show trends for <strong>Referrals</strong>, <strong>Visits</strong>, and new <strong>Affiliates</strong>.</p></li><li><p>Use the <strong>date range filter</strong> at the top right of the graph to view data for specific periods, such as the last month or the current year.</p></li></ul><h4 id="right-sidebar" tabindex="-1">Right Sidebar <a class="header-anchor" href="#right-sidebar" aria-label="Permalink to &quot;Right Sidebar&quot;">​</a></h4><p>The sidebar on the right gives you a real-time snapshot of recent activity.</p><ul><li><p><strong>Recent Referrals:</strong> This list shows the most recent sales made through your affiliate links. You can quickly see the product, the commission amount, the affiliate responsible, and the referral&#39;s status (e.g., Unpaid, Pending, or Paid). For detailed referral tracking and management, visit the <a href="/guide/admin-portal/managing-referrals">Managing Referrals</a> section.</p></li><li><p><strong>Top Affiliates:</strong> This is your affiliate leaderboard. It highlights your top-performing affiliates, showing their total number of referrals and their total earnings, making it easy to see who your most valuable partners are. You can click on any affiliate to view their detailed <a href="/guide/miscellaneous/affiliate-profile">profile</a>.</p></li></ul>',16)),a("p",null,[l(t,{src:"/guide/public/images/admin-portal/dashboard/admin-dashboard-overview.webp",alt:"Admin Dashboard Overview in FluentAffiliate"})]),e[1]||(e[1]=a("p",null,"That's a quick overview of your Admin Dashboard in FluentAffiliate.",-1))])}const b=r(h,[["render",d]]);export{v as __pageData,b as default};
